        "status": "final",
        "code": {
          "text": "Hydration and urine output"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Drinking water and Hydralyte; passing urine regularly, approximately 4–5 times per day, light yellow. Denies dizziness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "General fatigue"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Feels washed out."
      }
    },
