      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Diarrhoea onset and exposures"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Onset approximately 24 hours after eating a takeaway chicken burger. No travel, camping, or sick contacts. Completed amoxicillin/clavulanate approximately 2 weeks ago."
      }
    },
