      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "completed",
        "medicationCodeableConcept": {
          "text": "Amoxicillin/clavulanate 875 mg/125 mg"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "875 mg/125 mg twice daily for 7 days; course completed approximately 2 weeks ago"
          }
        ]
      }
    },
